mapper.select:
SELECT er.repair_id AS "repairId", be.equipment_name AS "equipmentName", er.fault_desc AS "faultDesc", er.status AS status, er.report_time AS "reportTime", er.finish_time AS "finishTime" FROM eqm_repair_order er LEFT JOIN base_equipment be ON be.equipment_id = er.equipment_id WHERE er.report_time >= #{start} AND er.report_time <= #{end}
AND be.unit_id IN
#{unitId}
AND (er.reporter_user_id = #{userId} OR er.handler_user_id = #{userId})
ORDER BY er.report_time DESC LIMIT 50
